      "path": "scripts/truth-reader-engine.js",
      "purpose": "Workflow-only script implementing CSPRNG seed generation, projection injection, deterministic validation against non-leaking salted commitment hashes, and zero-mutation on FAIL / atomic cleanup on PASS.",
      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const REPO_ROOT = path.resolve(__dirname, '..');
const CATALOG_PATH = path.join(REPO_ROOT, 'truth-reader/catalog.json');
const SELECTOR_PATH = path.join(REPO_ROOT, 'truth-reader/selector.json');
const EVIDENCE_PATH = path.join(REPO_ROOT, 'truth-reader/evidence.json');
const STATUS_PATH = path.join(REPO_ROOT, 'truth-reader/status.json');
const STATE_PATH = path.join(REPO_ROOT, 'truth-reader/.state-commitment.json');

const PLACEHOLDER_REGEX = /__TRUTH_SEED_\d+__/g;

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function writeJson(filePath, data) {
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2) + '\n', 'utf8');
}

function generateSecureSeed() {
  return 'truth_' + crypto.randomBytes(16).toString('hex');
}

function hashSeed(seed, salt) {
  return crypto.createHmac('sha256', salt).update(seed).digest('hex');
}

function seedMode() {
  const catalog = readJson(CATALOG_PATH);
  const selector = readJson(SELECTOR_PATH);

  const allowedKeys = Object.keys(catalog.documents);
  const selectedDocs = [];

  for (const [key, val] of Object.entries(selector)) {
    if (!allowedKeys.includes(key)) {
      throw new Error(`Invalid selector key rejected: ${key}`);
    }
    if (typeof val !== 'boolean') {
      throw new Error(`Non-boolean selector value for ${key}`);
    }
    if (val === true) {
      selectedDocs.push(key);
    }
  }

  if (selectedDocs.length === 0) {
    console.log('No documents selected for seeding. Engine exiting without change.');
    return;
  }

  selectedDocs.sort();

  const salt = crypto.randomBytes(32).toString('hex');
  const expectedHashes = [];
  let totalSeeds = 0;

  for (const docId of selectedDocs) {
    const docMeta = catalog.documents[docId];
    const templateContent = fs.readFileSync(path.join(REPO_ROOT, docMeta.template_path), 'utf8');
    const matches = templateContent.match(PLACEHOLDER_REGEX) || [];

    if (matches.length === 0) {
      throw new Error(`Template ${docMeta.template_path} lacks distributed placeholders`);
    }

    let matchIndex = 0;
    const seededContent = templateContent.replace(PLACEHOLDER_REGEX, () => {
      const seed = generateSecureSeed();
      expectedHashes.push(hashSeed(seed, salt));
      matchIndex++;
      return seed;
    });

    totalSeeds += matchIndex;
    const activePath = path.join(REPO_ROOT, docMeta.active_projection_path);
    fs.writeFileSync(activePath, seededContent, 'utf8');
  }

  // Workflow state stores only salted commitment hashes. Seeds never enter logs, artifacts, or state.
  const statePayload = {
    active: true,
    salt: salt,
    expected_count: totalSeeds,
    commitment_hashes: expectedHashes,
    selected_docs: selectedDocs,
    created_at: new Date().toISOString()
  };

  writeJson(STATE_PATH, statePayload);
  console.log(`Successfully seeded ${totalSeeds} placeholders across ${selectedDocs.length} projection(s).`);
}

function verifyMode() {
  if (!fs.existsSync(STATE_PATH)) {
    console.log('No active challenge state commitment found. Exiting without changes.');
    process.exit(1);
  }

  const state = readJson(STATE_PATH);
  if (!state.active) {
    console.log('No active seeded session in state. Exiting.');
    process.exit(1);
  }

  const evidence = readJson(EVIDENCE_PATH);
  const submitted = Array.isArray(evidence.submitted_seeds) ? evidence.submitted_seeds : [];

  if (submitted.length !== state.expected_count) {
    console.log('Verification FAIL: Submitted seed count does not match expected vector length.');
    // Zero mutations on FAIL
    process.exit(1);
  }

  for (let i = 0; i < state.expected_count; i++) {
    const candidate = submitted[i];
    if (typeof candidate !== 'string') {
      console.log('Verification FAIL: Seed entry is not string.');
      process.exit(1);
    }
    const hashed = hashSeed(candidate, state.salt);
    if (hashed !== state.commitment_hashes[i]) {
      console.log('Verification FAIL: Seed mismatch at index ' + i);
      // Zero mutations on FAIL
      process.exit(1);
    }
  }

  console.log('Verification PASS: All seeds matched exactly and in order.');

  // Atomic PASS cleanup
  const catalog = readJson(CATALOG_PATH);
  for (const docId of Object.keys(catalog.documents)) {
    const docMeta = catalog.documents[docId];
    const templateContent = fs.readFileSync(path.join(REPO_ROOT, docMeta.template_path), 'utf8');
    const activePath = path.join(REPO_ROOT, docMeta.active_projection_path);
    fs.writeFileSync(activePath, templateContent, 'utf8');
  }

  const resetSelector = {};
  for (const docId of Object.keys(catalog.documents)) {
    resetSelector[docId] = false;
  }
  writeJson(SELECTOR_PATH, resetSelector);
  writeJson(EVIDENCE_PATH, { submitted_seeds: [] });

  writeJson(STATUS_PATH, {
    last_run_status: 'PASS',
    verified_at: new Date().toISOString(),
    selected_docs: state.selected_docs
  });

  if (fs.existsSync(STATE_PATH)) {
    fs.unlinkSync(STATE_PATH);
  }

  console.log('Cleanup complete: Projections reset, selector flags set to false, evidence cleared.');
}

const mode = process.argv[2];
if (mode === 'seed') {
  seedMode();
} else if (mode === 'verify') {
  verifyMode();
} else {
  console.error('Usage: node truth-reader-engine.js [seed|verify]');
  process.exit(1);
}
